import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { fold } from "./fold";
import type { RawEvent } from "./types";

// X.46: the web fold and the Rust fold agree on logs a rewind can be in and
// on corrupt ones (a rewind naming no message of its turn counts for
// nothing). The logs and the Rust view are generated by
// crates/core/tests/rewind_fuzz.rs.
const logs = JSON.parse(readFileSync(new URL("./__fixtures__/rewind_fuzz.json", import.meta.url), "utf8")) as {
  seed: number;
  events: RawEvent[];
  items: unknown[];
  rewinds: unknown[];
  todo: unknown[];
}[];

describe("rewind: Rust and web folds on generated logs", () => {
  it("agree on the items with their marks, the rewinds and the task list", () => {
    const bad: number[] = [];
    let marked = 0;
    for (const l of logs) {
      const v = fold(l.events);
      if (JSON.stringify(l.items).includes('"rewound"')) marked++;
      try {
        expect({ items: v.items, rewinds: v.rewinds ?? [], todo: v.todo ?? [] }).toEqual({ items: l.items, rewinds: l.rewinds, todo: l.todo });
      } catch {
        bad.push(l.seed);
      }
    }
    expect(bad).toEqual([]);
    expect(marked).toBeGreaterThan(20);
    expect(logs.length).toBe(40);
  });
});
